import{_ as t,o as e,c as i,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-24（生物医学 / 植入式电催化 / 代谢疾病）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-24-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-24-biomed.md"}'),s={name:"topics/biomedicine/science-daily-2026-10-24-biomed.md"};function r(c,o,d,l,a,g){return e(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-24-生物医学-植入式电催化-代谢疾病" tabindex="-1">科学日报 · 2026-10-24（生物医学 / 植入式电催化 / 代谢疾病） <a class="header-anchor" href="#科学日报-·-2026-10-24-生物医学-植入式电催化-代谢疾病" aria-label="Permalink to &quot;科学日报 · 2026-10-24（生物医学 / 植入式电催化 / 代谢疾病）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> — 第43期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-24-植入式「电催化闭环」——不加药-把血糖直接氧化成葡萄糖酸排掉" tabindex="-1">科学日报 2026-10-24：植入式「电催化闭环」——不加药，把血糖直接氧化成葡萄糖酸排掉 <a class="header-anchor" href="#科学日报-2026-10-24-植入式「电催化闭环」——不加药-把血糖直接氧化成葡萄糖酸排掉" aria-label="Permalink to &quot;科学日报 2026-10-24：植入式「电催化闭环」——不加药，把血糖直接氧化成葡萄糖酸排掉&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1126/science.ady8560</p></blockquote><ul><li>临床背景：生活方式相关的 <strong>2 型糖尿病 + 肥胖（diabesity）影响 &gt;25 亿人</strong>，年医疗支出近 <strong>3 万亿美元</strong>。</li><li>器件 <strong>ECHO（electrocatalytic closed-loop health optimization）</strong>：<strong>可植入、无线供能</strong>，电极是<strong>石墨毡负载的「铂修饰金纳米簇」</strong>，实现<strong>选择性、可电调</strong>地把<strong>血糖氧化为经肾清除的葡萄糖酸（gluconate）</strong> —— 即<strong>用化学反应「消耗」血糖并把它变成可排泄的产物</strong>。</li><li>小鼠结果（2 型糖尿病模型）： <ul><li>无线低功率激活（<strong>0.75 V、10 mA</strong>）<strong>1 小时内恢复血糖稳态</strong>；</li><li><strong>代谢从葡萄糖利用转向脂质利用</strong>；</li><li><strong>降低体重与甘油三酯</strong>，升高<strong>循环游离脂肪酸与酮体</strong>；</li><li><strong>6 周治疗期间未检出低血糖</strong>，也无不良的生理、炎症或行为效应。</li></ul></li><li>闭环：与**商用连续血糖监测（CGM）**耦合 → <strong>手机控制的自主、非药物闭环管理</strong>。</li><li>洞察（对本库 <code>biomedicine</code> × <code>fitness</code>）：这条路的<strong>逻辑与主流完全不同</strong> —— GLP-1 类药物/胰岛素是**「调节生理信号」<strong>，ECHO 是</strong>「直接把代谢底物从血液里移走」**。两条关键设计判据值得记： <ul><li><strong>「低血糖风险来自『调节类』手段的过冲」</strong>：本条靠<strong>把血糖氧化成不回收的产物</strong>，等效于一个<strong>天然有下限的「漏」</strong>（没有血糖就没得氧化），因此<strong>不会过冲</strong> —— 这说明「<strong>剔除正反馈过冲</strong>」比「把控制器调得更准」更根本。</li><li><strong>「闭环的瓶颈往往是传感器而非执行器」</strong>：器件能把血糖拿掉，但要<strong>自主</strong>运行必须外接 CGM —— 与库内 10-23「个人健康智能体」（靠<strong>可穿戴数据</strong>做语境）<strong>同源</strong>：<strong>先有连续的测量，才有连续的干预</strong>。迁移判据：<strong>想要闭环，先解决「连续可测」，再谈「连续可控」。</strong></li></ul></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第43期 科学板块</p></blockquote><p>关键词：diabesity、2型糖尿病与肥胖、25 亿人、3 万亿美元、ECHO 器件、无线供能植入式、石墨毡、铂修饰金纳米簇、血糖选择性氧化为葡萄糖酸、肾清除、0.75V 10mA、1 小时恢复血糖稳态、转向脂质利用、降体重与甘油三酯、游离脂肪酸与酮体、6 周无低血糖、耦合 CGM、手机自主非药物闭环、漏式控制无过冲、先连续可测再连续可控</p><p>关联：<code>topics/biomedicine/science-daily-2026-10-23-biomed.md</code>、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>、<code>topics/fitness/index.md</code>、<code>topics/biomedicine/index.md</code></p>',10)])])}const b=t(s,[["render",r]]);export{p as __pageData,b as default};
